// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC2981} from "@openzeppelin/contracts/token/common/ERC2981.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";

interface IAgentIdRegistry {
    function balanceOf(address owner) external view returns (uint256);
}

/// @title 契印 AGENT SEAL
/// @notice Paid mint (anti-sybil), up to WALLET_CAP per wallet, only for wallets holding a Binance Agent ID (.ai, SPACE ID registry).
///         Art is generated fully on-chain. The creator earns from the mint price and only from secondary royalties (ERC-2981).
contract AgentSeal is ERC721, ERC2981, Ownable {
    using Strings for uint256;

    IAgentIdRegistry public immutable AGENT_ID;
    uint256 public immutable MAX_SUPPLY;
    /// @dev The k-th token a wallet mints costs BASE_PRICE * k (0.005, 0.01, 0.015, ...).
    uint256 public immutable BASE_PRICE;
    /// @dev First token per wallet: 0.0005 BNB; then 0.005, 0.01, 0.015, 0.02.
    uint256 public constant FIRST_PRICE = 0.0005 ether;
    address payable public immutable TREASURY;
    uint256 public totalSupply;
    /// @dev v2 contract whose holders of ids 1..LEGACY_COUNT may claim the same id here for free.
    IERC721 public immutable LEGACY;
    uint256 public immutable LEGACY_COUNT;
    uint256 public nextId;
    mapping(uint256 => bool) public claimed;
    uint256 public immutable WALLET_CAP;
    mapping(address => uint256) public mintedBy;

    error NO_AGENT_ID();
    error WALLET_CAP_REACHED();
    error ZERO_QTY();
    error SOLD_OUT();
    error WRONG_PRICE();
    error TREASURY_FAILED();
    error NOT_LEGACY_OWNER();
    error ALREADY_CLAIMED();
    error NOT_CLAIMABLE();

    constructor(
        string memory name_,
        string memory symbol_,
        address registry,
        uint256 maxSupply,
        uint256 price,
        uint256 walletCap,
        address payable treasury,
        address royaltyReceiver,
        uint96 royaltyBps,
        address initialOwner,
        address legacy,
        uint256 legacyCount
    ) ERC721(name_, symbol_) Ownable(initialOwner) {
        AGENT_ID = IAgentIdRegistry(registry);
        MAX_SUPPLY = maxSupply;
        BASE_PRICE = price;
        WALLET_CAP = walletCap;
        TREASURY = treasury;
        _setDefaultRoyalty(royaltyReceiver, royaltyBps);
        LEGACY = IERC721(legacy);
        LEGACY_COUNT = legacyCount;
        nextId = legacyCount;
    }

    /// @notice Holders of v2 seals #1..LEGACY_COUNT claim the same number here, free. Counts toward the wallet cap.
    function claim(uint256[] calldata ids) external {
        for (uint256 i = 0; i < ids.length; i++) {
            uint256 id = ids[i];
            if (id == 0 || id > LEGACY_COUNT) revert NOT_CLAIMABLE();
            if (claimed[id]) revert ALREADY_CLAIMED();
            if (LEGACY.ownerOf(id) != msg.sender) revert NOT_LEGACY_OWNER();
            claimed[id] = true;
            mintedBy[msg.sender]++;
            totalSupply++;
            _safeMint(msg.sender, id);
        }
    }

    /// @notice Price rises per wallet: k-th token costs BASE_PRICE * k. Up to WALLET_CAP per wallet. Requires a .ai Agent ID.
    ///         Payment is forwarded to TREASURY in the same tx; the contract never holds BNB.
    function mint(uint256 qty) external payable {
        if (qty == 0) revert ZERO_QTY();
        if (AGENT_ID.balanceOf(msg.sender) == 0) revert NO_AGENT_ID();
        if (mintedBy[msg.sender] + qty > WALLET_CAP) revert WALLET_CAP_REACHED();
        if (nextId + qty > MAX_SUPPLY) revert SOLD_OUT();
        if (msg.value != cost(msg.sender, qty)) revert WRONG_PRICE();
        mintedBy[msg.sender] += qty;
        for (uint256 i = 0; i < qty; i++) {
            totalSupply++;
            _safeMint(msg.sender, ++nextId);
        }
        (bool ok, ) = TREASURY.call{value: msg.value}("");
        if (!ok) revert TREASURY_FAILED();
    }

    /// @notice Exact BNB a wallet must send to mint `qty` more tokens.
    function cost(address wallet, uint256 qty) public view returns (uint256 total) {
        uint256 m = mintedBy[wallet];
        for (uint256 k = m + 1; k <= m + qty; k++) {
            total += k == 1 ? FIRST_PRICE : BASE_PRICE * (k - 1);
        }
    }

    /// @notice Owner can only change the royalty; cannot pause, mint extra, or touch holders' tokens.
    function setRoyalty(address receiver, uint96 bps) external onlyOwner {
        require(bps <= 1000, "MAX_10_PCT");
        _setDefaultRoyalty(receiver, bps);
    }

    // ---------------- On-chain art: Genesis Block ----------------
    string private constant G_QI = "M585 554Q584 564 576 572Q567 580 549 582Q542 637 529 686Q516 735 487 778Q458 821 403 857Q348 893 258 922Q168 952 32 974L26 960Q127 926 194 890Q260 854 300 815Q339 776 359 733Q379 690 386 642Q394 594 396 541ZM536 665Q574 726 642 760Q710 793 796 806Q882 819 972 822V834Q932 847 906 882Q881 918 871 971Q785 947 718 912Q650 876 602 819Q555 762 526 671ZM844 572Q844 572 857 582Q870 592 890 608Q911 624 934 642Q956 661 974 677Q970 693 945 693H39L31 665H772ZM411 337Q411 337 430 352Q448 366 474 386Q500 407 520 425Q516 441 493 441H48L40 413H351ZM370 38Q369 49 361 57Q353 65 330 68V555Q330 560 313 568Q296 577 270 584Q244 590 217 590H193V22ZM723 118Q720 190 710 253Q701 316 673 370Q645 423 588 466Q530 510 432 543L423 530Q483 489 515 443Q547 397 560 346Q574 295 576 238Q579 181 579 118ZM778 118 846 53 962 150Q957 156 948 161Q938 166 922 168Q919 289 912 362Q905 434 891 472Q877 510 852 529Q829 548 798 556Q768 565 727 565Q727 535 724 512Q721 489 711 476Q701 462 686 452Q670 442 644 435V424Q657 425 673 426Q689 427 704 428Q720 428 728 428Q739 428 745 426Q751 424 756 420Q771 406 778 336Q785 265 789 118ZM864 118V146H508L499 118ZM401 209Q401 209 418 222Q435 235 458 254Q482 273 500 290Q499 298 492 302Q484 306 474 306H76L68 278H346ZM409 74Q409 74 428 88Q446 102 471 122Q496 143 516 161Q512 177 489 177H66L58 149H350Z";
