    function _r(uint256 id, uint256 salt) internal pure returns (uint256) {
        return uint256(keccak256(abi.encode(id, salt, "SEAL5")));
    }

    function _ink(uint256 id) internal pure returns (string memory n, string memory c, string memory c2) {
        if (id <= 21) return ("Genesis Gold", "#f0c75e", "#ffe7a3");
        uint256 x = _r(id, 1) % 100;
        if (x < 45) return ("Satoshi Orange", "#f7931a", "#ffb653");
        if (x < 70) return ("Mint Gold", "#e6c46a", "#f5dc95");
        if (x < 85) return ("Silver", "#c9ced6", "#eef1f5");
        if (x < 95) return ("Terminal Green", "#3ddc84", "#8ff0b8");
        return ("Cypher Cyan", "#35d6e8", "#9cf1fa");
    }

    function _bg(uint256 id) internal pure returns (string memory n, string memory b1, string memory b2) {
        if (id <= 21) return ("Block Zero", "#1d1608", "#030201");
        uint256 x = _r(id, 2) % 100;
        if (x < 70) return ("Obsidian", "#1a1a1f", "#050507");
        if (x < 90) return ("Midnight", "#111a2e", "#04070f");
        return ("Bordeaux", "#2a1016", "#0b0406");
    }

    function _pad4(uint256 id) internal pure returns (string memory) {
        string memory s = id.toString();
        if (id < 10) return string.concat("000", s);
        if (id < 100) return string.concat("00", s);
        if (id < 1000) return string.concat("0", s);
        return s;
    }

    function _grid(uint256 id, bool mirrored, bool node, string memory c) internal pure returns (string memory g) {
        uint256 h = _r(id, 5);
        g = string.concat("<g fill='", c, "'>");
        for (uint256 i = 0; i < 64; i++) {
            uint256 x = i % 8;
            uint256 y = i / 8;
            uint256 bit = mirrored ? (h >> (y * 4 + (x < 4 ? x : 7 - x))) & 1 : (h >> i) & 1;
            uint256 px = 388 + x * 28;
            uint256 py = 358 + y * 28;
            if (bit == 1) {
                g = string.concat(g, node
                    ? string.concat("<circle cx='", (px + 12).toString(), "' cy='", (py + 12).toString(), "' r='11'/>")
                    : string.concat("<rect x='", px.toString(), "' y='", py.toString(), "' width='24' height='24' rx='3'/>"));
            } else {
                g = string.concat(g, "<rect x='", (px + 9).toString(), "' y='", (py + 9).toString(), "' width='6' height='6' fill-opacity='.3'/>");
            }
        }
        g = string.concat(g, "</g><text x='500' y='610' text-anchor='middle' font-family='Courier New,monospace' font-size='18' fill-opacity='.9' letter-spacing='4' fill='", c, "'>",
            Strings.toHexString(h >> 208, 6), "</text>");
    }

    function _tier(uint256 id) internal pure returns (string memory) {
        return id <= 21 ? "Genesis 21" : id <= 210 ? "Pioneer 210" : "Standard";
    }

