            "<path id='gp' d='M500 260a210 210 0 1 1 -.1 0'/></defs><rect width='1000' height='1000' fill='url(#b)'/>"
        );
        if (g21) s = string.concat(s, "<path d='M500 208L500 40M577 220L627 59M648 254L742 115M705 307L836 202M744 374L900 313M761 450L929 438M755 528L919 566M727 601L872 685M678 662L792 785M614 706L687 857M539 729L564 895M461 729L436 895M386 706L313 857M322 662L208 785M273 601L128 685M245 528L81 566M239 450L71 438M256 374L100 313M295 307L164 202M352 254L258 115M423 220L373 59' stroke='#f0c75e' stroke-width='2' opacity='.16'/>");
        s = string.concat(
            s, "<circle cx='500' cy='470' r='310' fill='url(#gl)'/><g fill='none' stroke='", frame, "'><rect x='36' y='36' width='928' height='928' stroke-width='",
            g21 ? "7" : p210 ? "4" : "2", "' opacity='.9'/><rect x='52' y='52' width='896' height='896' opacity='.5'/>",
            g21 ? "<rect x='22' y='22' width='956' height='956' stroke-width='2' opacity='.7'/>" : "",
            "<path stroke-width='3' d='M72 116V72h44M90 116V90h26M928 116V72h-44M910 116V90h-26M72 884v44h44M90 884v26h26M928 884v44h-44M910 884v26h-26'/></g>"
        );
        s = string.concat(
            s, "<g fill='none' stroke='", c, "'><circle cx='500' cy='470' r='242' stroke-width='3'/><circle cx='500' cy='470' r='182' stroke-width='3'/></g>",
            g21 ? "<path d='M500 209l6 7-6 7-6-7zM575 220l6 7-6 7-6-7zM643 253l6 7-6 7-6-7zM699 305l6 7-6 7-6-7zM736 370l6 7-6 7-6-7zM753 444l6 7-6 7-6-7zM748 520l6 7-6 7-6-7zM720 590l6 7-6 7-6-7zM673 649l6 7-6 7-6-7zM610 692l6 7-6 7-6-7zM538 714l6 7-6 7-6-7zM462 714l6 7-6 7-6-7zM390 692l6 7-6 7-6-7zM327 649l6 7-6 7-6-7zM280 590l6 7-6 7-6-7zM252 520l6 7-6 7-6-7zM247 444l6 7-6 7-6-7zM264 370l6 7-6 7-6-7zM301 305l6 7-6 7-6-7zM357 253l6 7-6 7-6-7zM425 220l6 7-6 7-6-7z' fill='#ffe7a3'/>" : p210 ? "<circle cx='500' cy='470' r='256' fill='none' stroke='url(#hg)' stroke-width='10' stroke-dasharray='2 5.6'/>" : "",
            "<text font-family='Courier New,monospace' font-size='15.5' letter-spacing='1' fill-opacity='.85' fill='", c,
            unicode"'><textPath href='#gp'>The Times 03/Jan/2009 Chancellor on brink of second bailout for banks ·· BLOCK 0 ··</textPath></text>",
            _grid(id, mirrored, node, c)
        );
        string memory gold = g21 ? "#f0c75e" : "#c9a45c";
        s = string.concat(
            s, "<g fill='", gold, "' font-family='Georgia,Times New Roman,serif' text-anchor='middle'><text x='500' y='140' font-size='30' letter-spacing='14'>AGENT SEAL</text>",
            unicode"<text x='500' y='176' font-size='15' letter-spacing='5' opacity='.75'>GENESIS BLOCK · 2009</text><g opacity='.9'><path transform='translate(470 190) scale(.028)' d='",
            G_QI, "'/><path transform='translate(502 190) scale(.028)' d='", G_YIN, "'/></g>",
            unicode"<text x='500' y='902' font-size='28' letter-spacing='6'>Nº ", _pad4(id), " / 2100</text>",
