        );
        if (g21) s = string.concat(s, unicode"<text x='500' y='852' font-size='16' letter-spacing='8'>GENESIS · 21</text>");
        else if (p210) s = string.concat(s, unicode"<text x='500' y='852' font-size='15' letter-spacing='8' fill='url(#hg)'>PIONEER · 210</text>");
