        attrs = string.concat(
            '[{"trait_type":"Tier","value":"', _tier(id), '"},{"trait_type":"Ink","value":"', inkN,
            '"},{"trait_type":"Background","value":"', bgN, '"},{"trait_type":"Pattern","value":"', mirrored ? "Mirrored" : "Raw",
            '"},{"trait_type":"Bits","value":"', node ? "Node" : "Block", '"}]'
        );
    }

    function tokenURI(uint256 id) public view override returns (string memory) {
        _requireOwned(id);
        (string memory svg, string memory attrs) = _svg(id);
        string memory json = string.concat(
            unicode'{"name":"契印 AGENT SEAL #', id.toString(),
            unicode'","description":"契印 AGENT SEAL：AI Agent 的链上印记。总量 2100，对应比特币 2100 万；以创世区块为印。仅 .ai Agent ID 持有者可铸，图像与元数据完全由合约生成。","attributes":', attrs,
            ',"image":"data:image/svg+xml;base64,', Base64.encode(bytes(svg)), '"}'
        );
        return string.concat("data:application/json;base64,", Base64.encode(bytes(json)));
    }

    function contractURI() external pure returns (string memory) {
        return string.concat("data:application/json;base64,", Base64.encode(bytes(unicode'{"name":"契印 AGENT SEAL","description":"AI Agent 的链上印记。2100 枚，创世区块风格，全链上 SVG。仅 .ai Agent ID 持有者可铸。","external_link":"https://agentseal.netlify.app"}')));
    }

    /// @notice Render any id (minted or not) for previews.
    function previewSVG(uint256 id) external pure returns (string memory svg) {
        (svg, ) = _svg(id);
    }

    function supportsInterface(bytes4 i) public view override(ERC721, ERC2981) returns (bool) {
        return super.supportsInterface(i);
    }
}

