// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/common/ERC2981.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

interface IAgentID { function balanceOf(address owner) external view returns (uint256); }

interface IHirelingsArt {
    function svg(uint256 id, uint256 seed, uint256 jobs, bool revealed) external pure returns (string memory);
    function attributes(uint256 seed, uint256 jobs, bool revealed) external pure returns (string memory);
}

/// @title HIRELINGS - 10,000 hireable .ai agents on BNB Chain
/// @notice 9,000 free mints for .ai Agent ID wallets, then 0.0005 BNB each, max 10 per wallet.
/// Anyone can hire an agent on the on-chain Job Board: the holder keeps 70% of the fee as wages,
/// 20% goes to the Payroll Pool and 10% to the treasury. The Payroll Pool also receives 30% of every
/// paid mint and 1% of every on-site trade, split equally across all minted agents, claimable by holders.
/// Referrers who hold an agent earn 20% of the paid mints they bring.
/// The owner can only switch phases and trigger the reveal; it can never touch pool, wage or referral funds.
/// Unofficial community project, not affiliated with Binance or BNB Chain. No return is promised.
contract Hirelings is ERC721, ERC2981, Ownable, ReentrancyGuard {
    using Strings for uint256;

    uint256 public constant MAX_SUPPLY = 10000;
    uint256 public constant FREE_SUPPLY = 9000;
    uint256 public constant MAX_PER_WALLET = 10;
    uint256 public constant PRICE = 0.0005 ether;
    uint256 public constant BASE_RATE = 0.0005 ether;
    uint256 public constant REF_BPS = 2000;
    uint256 public constant POOL_MINT_BPS = 3000;
    uint256 public constant WAGE_BPS = 7000;
    uint256 public constant POOL_HIRE_BPS = 2000;
    uint256 public constant MARKET_FEE_BPS = 200;
    IAgentID public constant AGENT_ID = IAgentID(0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F);

    address payable public immutable TREASURY;
    IHirelingsArt public immutable ART;

    bool public freeMintOpen;
    bool public paidMintOpen;
    bool public marketOpen;
    bool public hireOpen;
    bool public paidRequiresAgentId = true;
    uint256 public freePerWallet = 2;
    bool public xTaskRequired;
    string public xTaskUrl;

    uint256 public totalMinted;
    uint256 public freeMinted;
    bool public revealed;
    uint256 public revealSeed;

    mapping(address => uint256) public mintedBy;
    mapping(address => uint256) public freeUsed;

    uint256 public accPerAgent;
    uint256 public poolTotalIn;
    uint256 public poolTotalClaimed;
    mapping(uint256 => uint256) public paidPerAgent;

    mapping(address => uint256) public owed;
    mapping(address => uint256) public refEarned;
    mapping(address => uint256) public refCount;
    mapping(address => uint256) public wagesEarned;
    uint256 public refTotalPaid;

    mapping(uint256 => uint256) public jobs;
    mapping(uint256 => uint256) public customRate;
    uint256 public totalJobs;
    uint256 public totalWages;

    mapping(uint256 => uint256) public listing;
    uint256 public marketVolume;
    uint256 public marketSales;

    event PhaseChanged(string phase, bool open);
    event XTask(bool required, string url);
    event Revealed(uint256 seed);
    event PoolIn(uint256 amount, string source);
    event Claimed(address indexed holder, uint256 amount);
    event Withdrawn(address indexed who, uint256 amount);
    event Referral(address indexed referrer, address indexed minter, uint256 amount);
    event Hired(uint256 indexed id, address indexed client, address indexed holder, uint256 fee, string brief);
    event RateSet(uint256 indexed id, uint256 rate);
    event Listed(uint256 indexed id, uint256 price);
    event Unlisted(uint256 indexed id);
    event Sold(uint256 indexed id, address indexed seller, address indexed buyer, uint256 price);
    event MetadataUpdate(uint256 _tokenId);
    event BatchMetadataUpdate(uint256 _fromTokenId, uint256 _toTokenId);

    constructor(address art, address payable treasury) ERC721("HIRELINGS", "HIRE") Ownable(treasury) {
        ART = IHirelingsArt(art);
        TREASURY = treasury;
        _setDefaultRoyalty(treasury, 500);
    }

    // ---------------- owner switches ----------------
    function setFreeMint(bool o) external onlyOwner { freeMintOpen = o; emit PhaseChanged("freeMint", o); }
    function setPaidMint(bool o) external onlyOwner { paidMintOpen = o; emit PhaseChanged("paidMint", o); }
    function setMarket(bool o) external onlyOwner { marketOpen = o; emit PhaseChanged("market", o); }
    function setHire(bool o) external onlyOwner { hireOpen = o; emit PhaseChanged("hire", o); }
    function setPaidRequiresAgentId(bool o) external onlyOwner { paidRequiresAgentId = o; emit PhaseChanged("paidRequiresAgentId", o); }
    function setFreePerWallet(uint256 n) external onlyOwner { require(n >= 1 && n <= MAX_PER_WALLET, "1-10"); freePerWallet = n; }
    /// @notice X task gate shown on the website (follow / like / repost the pinned post). Enforced by the site, not on-chain.
    function setXTask(bool required, string calldata url) external onlyOwner { xTaskRequired = required; xTaskUrl = url; emit XTask(required, url); }
    /// @notice Opens free mint, paid mint and market in one transaction.
    function launch() external onlyOwner {
        freeMintOpen = true; paidMintOpen = true; marketOpen = true;
        emit PhaseChanged("freeMint", true); emit PhaseChanged("paidMint", true); emit PhaseChanged("market", true);
    }

    function reveal() external {
        require(!revealed, "revealed");
        require(msg.sender == owner() || totalMinted == MAX_SUPPLY, "not allowed");
        revealed = true;
        revealSeed = uint256(keccak256(abi.encode(block.prevrandao, blockhash(block.number - 1), totalMinted, address(this))));
        emit Revealed(revealSeed);
        emit BatchMetadataUpdate(1, MAX_SUPPLY);
    }

    // ---------------- mint ----------------
    function freeAvailable(address a) public view returns (uint256) {
        if (!freeMintOpen || AGENT_ID.balanceOf(a) == 0 || freeUsed[a] >= freePerWallet) return 0;
        uint256 w = freePerWallet - freeUsed[a];
        uint256 g = FREE_SUPPLY - freeMinted;
        uint256 m = MAX_PER_WALLET - mintedBy[a];
        if (g < w) w = g;
        return m < w ? m : w;
    }

    function quote(address a, uint256 qty) external view returns (uint256 free, uint256 cost) {
        free = freeAvailable(a); if (free > qty) free = qty;
        cost = (qty - free) * PRICE;
    }

    function mint(uint256 qty, address ref) external payable nonReentrant {
        require(qty > 0, "qty");
        require(totalMinted + qty <= MAX_SUPPLY, "sold out");
        require(mintedBy[msg.sender] + qty <= MAX_PER_WALLET, "wallet max 10");
        uint256 free = freeAvailable(msg.sender); if (free > qty) free = qty;
        uint256 paid = qty - free;
        if (paid > 0) {
            require(paidMintOpen, "paid mint closed");
            if (paidRequiresAgentId) require(AGENT_ID.balanceOf(msg.sender) > 0, "need .ai Agent ID");
        } else {
            require(freeMintOpen, "free mint closed");
        }
        require(msg.value == paid * PRICE, "wrong value");
        freeUsed[msg.sender] += free; freeMinted += free; mintedBy[msg.sender] += qty;
        uint256 start = totalMinted;
        totalMinted = start + qty;
        for (uint256 i = 1; i <= qty; i++) {
            paidPerAgent[start + i] = accPerAgent;
            _mint(msg.sender, start + i);
        }
        if (msg.value > 0) {
            uint256 v = msg.value;
            uint256 toRef;
            if (ref != address(0) && ref != msg.sender && balanceOf(ref) > 0) {
                toRef = v * REF_BPS / 10000;
                owed[ref] += toRef; refEarned[ref] += toRef; refCount[ref] += paid; refTotalPaid += toRef;
                emit Referral(ref, msg.sender, toRef);
            }
            uint256 toPool = v * POOL_MINT_BPS / 10000;
            _toPool(toPool, "mint");
            _pay(TREASURY, v - toRef - toPool);
        }
    }

    // ---------------- Job Board ----------------
    function rateOf(uint256 id) public view returns (uint256) { uint256 r = customRate[id]; return r == 0 ? BASE_RATE : r; }

    function setRate(uint256 id, uint256 rate) external {
        require(ownerOf(id) == msg.sender, "not holder");
        require(rate == 0 || (rate >= 0.0001 ether && rate <= 1 ether), "rate");
        customRate[id] = rate;
        emit RateSet(id, rateOf(id));
    }

    function hire(uint256 id, string calldata brief) external payable nonReentrant {
        require(hireOpen, "job board closed");
        address holder = ownerOf(id);
        require(holder != msg.sender, "own agent");
        require(bytes(brief).length > 0 && bytes(brief).length <= 140, "brief 1-140");
        uint256 fee = rateOf(id);
        require(msg.value == fee, "wrong value");
        uint256 wage = fee * WAGE_BPS / 10000;
        uint256 toPool = fee * POOL_HIRE_BPS / 10000;
        owed[holder] += wage; wagesEarned[holder] += wage; totalWages += wage;
        jobs[id] += 1; totalJobs += 1;
        _toPool(toPool, "hire");
        _pay(TREASURY, fee - wage - toPool);
        emit Hired(id, msg.sender, holder, fee, brief);
        emit MetadataUpdate(id);
    }

    function rank(uint256 id) public view returns (uint256) { uint256 j = jobs[id]; return j >= 50 ? 4 : j >= 25 ? 3 : j >= 10 ? 2 : j >= 3 ? 1 : 0; }

    // ---------------- Payroll Pool ----------------
    function _toPool(uint256 amt, string memory src) private {
        if (amt == 0 || totalMinted == 0) return;
        accPerAgent += amt * 1e18 / totalMinted;
        poolTotalIn += amt;
        emit PoolIn(amt, src);
    }

    function claimable(uint256 id) public view returns (uint256) {
        if (id == 0 || id > totalMinted) return 0;
        return (accPerAgent - paidPerAgent[id]) / 1e18;
    }

    function claim(uint256[] calldata ids) external nonReentrant {
        uint256 sum;
        for (uint256 i; i < ids.length; i++) {
            uint256 id = ids[i];
            require(ownerOf(id) == msg.sender, "not holder");
            uint256 c = (accPerAgent - paidPerAgent[id]) / 1e18;
            paidPerAgent[id] += c * 1e18;
            sum += c;
        }
        require(sum > 0, "nothing");
        poolTotalClaimed += sum;
        _pay(payable(msg.sender), sum);
        emit Claimed(msg.sender, sum);
    }

    /// @notice Withdraw wages + referral rewards.
    function withdraw() external nonReentrant {
        uint256 a = owed[msg.sender];
        require(a > 0, "nothing");
        owed[msg.sender] = 0;
        _pay(payable(msg.sender), a);
        emit Withdrawn(msg.sender, a);
    }

    // ---------------- Market (no approvals) ----------------
    function list(uint256 id, uint256 price) external {
        require(marketOpen, "market closed");
        require(ownerOf(id) == msg.sender, "not holder");
        require(price >= 0.00001 ether && price <= 1000 ether, "price");
        listing[id] = price;
        emit Listed(id, price);
    }

    function unlist(uint256 id) external {
        require(ownerOf(id) == msg.sender, "not holder");
        delete listing[id];
        emit Unlisted(id);
    }

    function buy(uint256 id) external payable nonReentrant {
        require(marketOpen, "market closed");
        uint256 p = listing[id];
        require(p > 0, "not listed");
        require(msg.value == p, "wrong value");
        address seller = ownerOf(id);
        require(seller != msg.sender, "own");
        _transfer(seller, msg.sender, id);
        uint256 fee = p * MARKET_FEE_BPS / 10000;
        uint256 half = fee / 2;
        _toPool(half, "market");
        _pay(TREASURY, fee - half);
        _pay(payable(seller), p - fee);
        marketVolume += p; marketSales += 1;
        emit Sold(id, seller, msg.sender, p);
    }

    // ---------------- views ----------------
    struct Row { address holder; uint256 price; uint256 claimable; uint256 jobs; uint256 rate; }

    function scan(uint256 from, uint256 count) external view returns (Row[] memory rows) {
        if (from == 0) from = 1;
        uint256 end = from + count; if (end > totalMinted + 1) end = totalMinted + 1;
        if (end <= from) return rows;
        rows = new Row[](end - from);
        for (uint256 id = from; id < end; id++) rows[id - from] = Row(_ownerOf(id), listing[id], claimable(id), jobs[id], rateOf(id));
    }

    function stats() external view returns (uint256[16] memory s) {
        s = [totalMinted, freeMinted, poolTotalIn, poolTotalClaimed, refTotalPaid, marketVolume, marketSales, totalJobs, totalWages,
            revealed ? 1 : 0, freeMintOpen ? 1 : 0, paidMintOpen ? 1 : 0, marketOpen ? 1 : 0, hireOpen ? 1 : 0,
            paidRequiresAgentId ? 1 : 0, xTaskRequired ? 1 : 0];
    }

    function seedOf(uint256 id) public view returns (uint256) { return uint256(keccak256(abi.encode(revealSeed, id))); }

    function tokenURI(uint256 id) public view override returns (string memory) {
        _requireOwned(id);
        uint256 s = seedOf(id);
        string memory img = Base64.encode(bytes(ART.svg(id, s, jobs[id], revealed)));
        return string.concat("data:application/json;base64,", Base64.encode(bytes(string.concat(
            "{\"name\":\"HIRELING #", id.toString(),
            "\",\"description\":\"HIRELINGS: 10,000 hireable .ai agents on BNB Chain. Hire an agent on the on-chain Job Board, holders earn wages. 100% on-chain. https://hirelings.pages.dev\",\"image\":\"data:image/svg+xml;base64,",
            img, "\",\"attributes\":", ART.attributes(s, jobs[id], revealed), "}"))));
    }

    function contractURI() external pure returns (string memory) {
        return "data:application/json;utf8,{\"name\":\"HIRELINGS\",\"description\":\"10,000 hireable .ai agents on BNB Chain. Free mint for .ai Agent ID holders. Holders earn wages from the on-chain Job Board.\",\"external_link\":\"https://hirelings.pages.dev\"}";
    }

    function _update(address to, uint256 id, address auth) internal override returns (address from) {
        from = super._update(to, id, auth);
        if (listing[id] != 0) { delete listing[id]; emit Unlisted(id); }
    }

    function _pay(address payable to, uint256 amt) private {
        if (amt == 0) return;
        (bool ok,) = to.call{value: amt}("");
        require(ok, "pay failed");
    }

    function supportsInterface(bytes4 i) public view override(ERC721, ERC2981) returns (bool) {
        return i == bytes4(0x49064906) || super.supportsInterface(i);
    }
}

