// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/common/ERC2981.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

interface IAgentID { function balanceOf(address owner) external view returns (uint256); }
interface IRego { function mint(address to, uint256 amt) external returns (uint256); }
interface IMachines {
    function mint(address to, uint256 t, uint256 n) external;
    function burn(address from, uint256 t, uint256 n) external;
}
interface IMarsArt {
    function plotSvg(uint256 id, uint256 seed, uint256 terrain, bool revealed, uint8[5] memory m, string memory nm) external view returns (string memory);
    function terrainName(uint256 t) external view returns (string memory);
}

/// @title MARS PLOTS - 10,000 land plots on Mars, BNB Chain
/// @notice One plot per wallet, free for .ai Agent ID wallets (optional: pick your cell +0.001 BNB, Starter Pack +0.0005 BNB).
/// Plots mine REGO every day (halving every 180 days, hard cap 1B). Machines (0.0005 BNB) boost mining.
/// 30% of claim, machine, slot and name fees plus 1% of every on-site trade go to the Plot Vault, split equally per plot, claimable in BNB.
/// Terrain is hidden until reveal (90% minted), so paying to pick a cell never buys rarity.
/// The owner can only switch phases and reveal; it can never touch vault funds or mined REGO.
/// Unofficial community project, not affiliated with Binance or BNB Chain. No return is promised.
contract MarsPlots is ERC721, ERC2981, Ownable, ReentrancyGuard {
    using Strings for uint256;

    uint256 public constant MAX_SUPPLY = 10000;
    uint256 public constant REVEAL_AT = 9000;
    uint256 public constant PICK_FEE = 0.001 ether;
    uint256 public constant PACK_FEE = 0.0005 ether;
    uint256 public constant MACHINE_PRICE = 0.0005 ether;
    uint256 public constant CLAIM_FEE = 0.0001 ether;
    uint256 public constant NAME_FEE = 0.001 ether;
    uint256 public constant VAULT_BPS = 3000;
    uint256 public constant MARKET_FEE_BPS = 200; // 1% vault + 1% treasury
    uint256 public constant BASE_PER_DAY = 100 ether;
    uint256 public constant HALVING = 180 days;
    IAgentID public constant AGENT_ID = IAgentID(0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F);

    address payable public immutable TREASURY;
    IMarsArt public immutable ART;
    address private immutable INITIALIZER;
    IRego public rego;
    IMachines public machines;

    bool public mintOpen;
    bool public openToAll;
    bool public miningOpen;
    bool public machinesOpen;
    bool public marketOpen;

    uint256 public totalMinted;
    bool public revealed;
    uint256 public revealSeed;
    uint256 public miningStart;
    mapping(address => bool) public hasMinted;

    // random cell pool (swap-remove)
    mapping(uint256 => uint256) private _val; // index -> cell (0 = index+1)
    mapping(uint256 => uint256) private _pos; // cell -> index+1 (0 = cell-1)

    // plots
    mapping(uint256 => uint8[5]) private _mach;
    mapping(uint256 => uint8) private _extraSlots; // 0..3 on top of 2
    mapping(uint256 => uint64) public lastT;
    mapping(uint256 => uint256) public banked;
    mapping(uint256 => string) public plotName;
    uint256 public totalMined;
    uint256[6] public machinesMinted;

    // vault
    uint256 public accPerPlot;
    uint256 public vaultTotalIn;
    uint256 public vaultTotalClaimed;
    mapping(uint256 => uint256) public paidPerPlot;

    // market
    mapping(uint256 => uint256) public listing;
    uint256 public marketVolume;
    uint256 public marketSales;

    event PhaseChanged(string phase, bool open);
    event Revealed(uint256 seed);
    event PlotMinted(address indexed to, uint256 indexed id, bool picked, bool pack);
    event Mined(address indexed to, uint256 amount);
    event MachinesBought(address indexed to, uint8[] types);
    event Attached(uint256 indexed id, uint256 machine);
    event Detached(uint256 indexed id, uint256 machine);
    event SlotUnlocked(uint256 indexed id, uint256 slots);
    event Named(uint256 indexed id, string name);
    event VaultIn(uint256 amount, string source);
    event VaultClaimed(address indexed holder, uint256 amount);
    event Listed(uint256 indexed id, uint256 price);
    event Unlisted(uint256 indexed id);
    event Sold(uint256 indexed id, address indexed seller, address indexed buyer, uint256 price);
    event MetadataUpdate(uint256 _tokenId);
    event BatchMetadataUpdate(uint256 _fromTokenId, uint256 _toTokenId);

    constructor(address art, address payable treasury) ERC721("MARS PLOTS", "PLOT") Ownable(treasury) {
        ART = IMarsArt(art);
        TREASURY = treasury;
        INITIALIZER = tx.origin;
        _setDefaultRoyalty(treasury, 500);
    }

    /// @notice One-time wiring of REGO and Machines, only by the deploying account.
    function init(address r, address m) external {
        require(tx.origin == INITIALIZER && address(rego) == address(0), "init");
        rego = IRego(r); machines = IMachines(m);
    }

    // ---------------- owner switches ----------------
    function setMint(bool o) external onlyOwner { mintOpen = o; emit PhaseChanged("mint", o); }
    function setOpenToAll(bool o) external onlyOwner { openToAll = o; emit PhaseChanged("openToAll", o); }
    function setMachines(bool o) external onlyOwner { machinesOpen = o; emit PhaseChanged("machines", o); }
    function setMarket(bool o) external onlyOwner { marketOpen = o; emit PhaseChanged("market", o); }
    function setMining(bool o) external onlyOwner {
        require(revealed, "reveal first");
        if (o && miningStart == 0) miningStart = block.timestamp;
        miningOpen = o; emit PhaseChanged("mining", o);
    }
    /// @notice Opens plot mint and the market in one transaction.
    function launch() external onlyOwner {
        mintOpen = true; marketOpen = true;
        emit PhaseChanged("mint", true); emit PhaseChanged("market", true);
    }
    /// @notice Owner may reveal any time; anyone may reveal once 9,000 plots are minted.
    function reveal() external {
        require(!revealed, "revealed");
        require(msg.sender == owner() || totalMinted >= REVEAL_AT, "not allowed");
        revealed = true;
        revealSeed = uint256(keccak256(abi.encode(block.prevrandao, blockhash(block.number - 1), totalMinted, address(this))));
        emit Revealed(revealSeed);
        emit BatchMetadataUpdate(1, MAX_SUPPLY);
    }

    // ---------------- plot mint ----------------
    function canMint(address a) public view returns (bool) {
        return mintOpen && !hasMinted[a] && totalMinted < MAX_SUPPLY && (openToAll || AGENT_ID.balanceOf(a) > 0);
    }
    function mintPrice(bool pick, bool pack) public pure returns (uint256) {
        return (pick ? PICK_FEE : 0) + (pack ? PACK_FEE : 0);
    }
    function isFree(uint256 cell) public view returns (bool) { return cell >= 1 && cell <= MAX_SUPPLY && _ownerOf(cell) == address(0); }

    function _cellAt(uint256 i) private view returns (uint256) { uint256 v = _val[i]; return v == 0 ? i + 1 : v; }
    function _idxOf(uint256 c) private view returns (uint256) { uint256 p = _pos[c]; return p == 0 ? c - 1 : p - 1; }
    function _take(uint256 i) private returns (uint256 cell) {
        uint256 last = MAX_SUPPLY - totalMinted - 1;
        cell = _cellAt(i);
        uint256 lc = _cellAt(last);
        _val[i] = lc; _pos[lc] = i + 1;
        delete _val[last];
    }

    /// @param cell 0 = random cell, 1..10000 = pick that cell (+0.001 BNB). Cell n is at X=(n-1)%100, Y=(n-1)/100.
    /// @param pack Starter Pack (+0.0005 BNB): a Solar Array is installed on the plot.
    function mint(uint256 cell, bool pack) external payable nonReentrant returns (uint256 id) {
        require(mintOpen, "mint closed");
        require(!hasMinted[msg.sender], "1 per wallet");
        require(totalMinted < MAX_SUPPLY, "sold out");
        require(openToAll || AGENT_ID.balanceOf(msg.sender) > 0, "need .ai Agent ID");
        require(msg.value == mintPrice(cell != 0, pack), "wrong value");
        if (cell == 0) {
            uint256 left = MAX_SUPPLY - totalMinted;
            uint256 r = uint256(keccak256(abi.encode(block.prevrandao, msg.sender, totalMinted, blockhash(block.number - 1))));
            id = _take(r % left);
        } else {
            require(isFree(cell), "cell taken");
            id = _take(_idxOf(cell));
        }
        hasMinted[msg.sender] = true;
        totalMinted += 1;
        paidPerPlot[id] = accPerPlot;
        lastT[id] = uint64(block.timestamp);
        if (pack) { _mach[id][0] = 1; machinesMinted[1] += 1; }
        _mint(msg.sender, id);
        emit PlotMinted(msg.sender, id, cell != 0, pack);
        _pay(TREASURY, msg.value);
    }

    // ---------------- terrain & mining ----------------
    function terrainOf(uint256 id) public view returns (uint256) {
        if (!revealed) return 255;
        uint256 r = uint256(keccak256(abi.encode(revealSeed, id))) % 100;
        return r < 50 ? 0 : r < 75 ? 1 : r < 90 ? 2 : r < 98 ? 3 : 4;
    }
    function terrainMult(uint256 t) public pure returns (uint256) { return t == 0 ? 100 : t == 1 ? 150 : t == 2 ? 200 : t == 3 ? 300 : t == 4 ? 500 : 0; }
    function slotsOf(uint256 id) public view returns (uint256) { return 2 + _extraSlots[id]; }
    function machinesOf(uint256 id) external view returns (uint8[5] memory) { return _mach[id]; }
    function boostOf(uint256 id) public view returns (uint256 b) {
        uint8[5] memory m = _mach[id];
        for (uint256 i; i < 5; i++) b += m[i] == 1 ? 20 : m[i] == 2 ? 35 : m[i] == 3 ? 50 : m[i] == 4 ? 75 : m[i] == 5 ? 150 : 0;
    }
    /// @notice REGO per day for this plot right now (18 decimals).
    function ratePerDay(uint256 id) public view returns (uint256) {
        if (miningStart == 0 || _ownerOf(id) == address(0)) return 0;
        uint256 e = (block.timestamp - miningStart) / HALVING; if (e > 64) return 0;
        return (BASE_PER_DAY >> e) * terrainMult(terrainOf(id)) * (100 + boostOf(id)) / 10000;
    }
    /// @dev REGO emitted per 1x plot from mining start until t, with halving.
    function cumAt(uint256 t) public view returns (uint256) {
        if (miningStart == 0 || t <= miningStart) return 0;
        uint256 d = t - miningStart; uint256 e = d / HALVING;
        uint256 perEpoch = BASE_PER_DAY * 180;
        if (e >= 64) return perEpoch * 2;
        return perEpoch * 2 - (perEpoch * 2 >> e) + (((d - e * HALVING) * BASE_PER_DAY / 1 days) >> e);
    }
    function _fresh(uint256 id) private view returns (uint256) {
        if (miningStart == 0 || !miningOpen) return 0;
        uint256 from = lastT[id] < miningStart ? miningStart : lastT[id];
        if (block.timestamp <= from) return 0;
        return (cumAt(block.timestamp) - cumAt(from)) * terrainMult(terrainOf(id)) * (100 + boostOf(id)) / 10000;
    }
    function pending(uint256 id) public view returns (uint256) { return banked[id] + _fresh(id); }
    function _bank(uint256 id) private { banked[id] += _fresh(id); lastT[id] = uint64(block.timestamp); }

    /// @notice Claim mined REGO from your plots. Fee 0.0001 BNB per claim (any number of plots).
    function claim(uint256[] calldata ids) external payable nonReentrant {
        require(miningOpen, "mining closed");
        require(msg.value == CLAIM_FEE, "wrong value");
        uint256 sum;
        for (uint256 i; i < ids.length; i++) {
            require(ownerOf(ids[i]) == msg.sender, "not owner");
            sum += pending(ids[i]); banked[ids[i]] = 0; lastT[ids[i]] = uint64(block.timestamp);
        }
        require(sum > 0, "nothing");
        uint256 got = rego.mint(msg.sender, sum);
        totalMined += got;
        emit Mined(msg.sender, got);
        _fee(msg.value, "claim");
    }

    // ---------------- machines ----------------
    /// @notice Buy 1-10 random machines at 0.0005 BNB each. Solar 40% · Drill 28% · Rover 18% · Hab 11% · Fusion 3%.
    function buyMachines(uint256 n) external payable nonReentrant {
        require(machinesOpen, "machines closed");
        require(n >= 1 && n <= 10, "1-10");
        require(msg.value == n * MACHINE_PRICE, "wrong value");
        uint8[] memory got = new uint8[](n);
        uint256 seed = uint256(keccak256(abi.encode(block.prevrandao, msg.sender, blockhash(block.number - 1), machinesMinted[0])));
        for (uint256 i; i < n; i++) {
            uint256 r = uint256(keccak256(abi.encode(seed, i))) % 100;
            uint8 t = r < 40 ? 1 : r < 68 ? 2 : r < 86 ? 3 : r < 97 ? 4 : 5;
            got[i] = t; machinesMinted[t] += 1;
            machines.mint(msg.sender, t, 1);
        }
        machinesMinted[0] += n;
        emit MachinesBought(msg.sender, got);
        _fee(msg.value, "machine");
    }

    function attach(uint256 id, uint256 t) external nonReentrant {
        require(ownerOf(id) == msg.sender, "not owner");
        require(t >= 1 && t <= 5, "type");
        uint256 s = slotsOf(id); uint256 i;
        while (i < s && _mach[id][i] != 0) i++;
        require(i < s, "slots full");
        _bank(id);
        machines.burn(msg.sender, t, 1);
        _mach[id][i] = uint8(t);
        emit Attached(id, t); emit MetadataUpdate(id);
    }

    function detach(uint256 id, uint256 slot) external nonReentrant {
        require(ownerOf(id) == msg.sender, "not owner");
        uint256 t = _mach[id][slot];
        require(t != 0, "empty");
        _bank(id);
        _mach[id][slot] = 0;
        machines.mint(msg.sender, t, 1);
        emit Detached(id, t); emit MetadataUpdate(id);
    }

    function slotFee(uint256 id) public view returns (uint256) {
        uint256 e = _extraSlots[id]; return e == 0 ? 0.0005 ether : e == 1 ? 0.001 ether : e == 2 ? 0.002 ether : 0;
    }
    /// @notice Unlock machine slot 3 / 4 / 5 for 0.0005 / 0.001 / 0.002 BNB.
    function unlockSlot(uint256 id) external payable nonReentrant {
        require(ownerOf(id) == msg.sender, "not owner");
        require(_extraSlots[id] < 3, "max slots");
        require(msg.value == slotFee(id), "wrong value");
        _extraSlots[id] += 1;
        emit SlotUnlocked(id, slotsOf(id));
        _fee(msg.value, "slot");
    }

    /// @notice Name your plot (1-16 chars: A-Z a-z 0-9 space - .). Fee 0.001 BNB.
    function setName(uint256 id, string calldata nm) external payable nonReentrant {
        require(ownerOf(id) == msg.sender, "not owner");
        require(msg.value == NAME_FEE, "wrong value");
        bytes memory b = bytes(nm);
        require(b.length >= 1 && b.length <= 16, "length");
        for (uint256 i; i < b.length; i++) {
            bytes1 c = b[i];
            require((c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || (c >= "0" && c <= "9") || c == " " || c == "-" || c == ".", "chars");
        }
        plotName[id] = nm;
        emit Named(id, nm); emit MetadataUpdate(id);
        _fee(msg.value, "name");
    }

    // ---------------- Plot Vault ----------------
    function _fee(uint256 v, string memory src) private {
        uint256 toV = v * VAULT_BPS / 10000;
        if (totalMinted == 0) toV = 0;
        if (toV > 0) { accPerPlot += toV * 1e18 / totalMinted; vaultTotalIn += toV; emit VaultIn(toV, src); }
        _pay(TREASURY, v - toV);
    }
    function vaultClaimable(uint256 id) public view returns (uint256) {
        if (_ownerOf(id) == address(0)) return 0;
        return (accPerPlot - paidPerPlot[id]) / 1e18;
    }
    function claimVault(uint256[] calldata ids) external nonReentrant {
        uint256 sum;
        for (uint256 i; i < ids.length; i++) {
            require(ownerOf(ids[i]) == msg.sender, "not owner");
            uint256 c = (accPerPlot - paidPerPlot[ids[i]]) / 1e18;
            paidPerPlot[ids[i]] += c * 1e18; sum += c;
        }
        require(sum > 0, "nothing");
        vaultTotalClaimed += sum;
        _pay(payable(msg.sender), sum);
        emit VaultClaimed(msg.sender, sum);
    }

    // ---------------- Market (no approvals) ----------------
    function list(uint256 id, uint256 price) external {
        require(marketOpen, "market closed");
        require(ownerOf(id) == msg.sender, "not owner");
        require(price >= 0.00001 ether && price <= 1000 ether, "price");
        listing[id] = price; emit Listed(id, price);
    }
    function unlist(uint256 id) external {
        require(ownerOf(id) == msg.sender, "not owner");
        delete listing[id]; emit Unlisted(id);
    }
    function buy(uint256 id) external payable nonReentrant {
        require(marketOpen, "market closed");
        uint256 p = listing[id];
        require(p > 0, "not listed");
        require(msg.value == p, "wrong value");
        address seller = ownerOf(id);
        require(seller != msg.sender, "own");
        _transfer(seller, msg.sender, id);
        uint256 fee = p * MARKET_FEE_BPS / 10000;
        uint256 half = fee / 2;
        accPerPlot += half * 1e18 / totalMinted; vaultTotalIn += half; emit VaultIn(half, "market");
        _pay(TREASURY, fee - half);
        _pay(payable(seller), p - fee);
        marketVolume += p; marketSales += 1;
        emit Sold(id, seller, msg.sender, p);
    }

    // ---------------- views ----------------
    struct Cell { address owner; uint256 price; uint16 boost; uint8 terrain; }
    /// @notice Map scan by cell id range (1..10000).
    function scan(uint256 from, uint256 count) external view returns (Cell[] memory rows) {
        if (from == 0) from = 1;
        uint256 end = from + count; if (end > MAX_SUPPLY + 1) end = MAX_SUPPLY + 1;
        if (end <= from) return rows;
        rows = new Cell[](end - from);
        for (uint256 id = from; id < end; id++) {
            address o = _ownerOf(id);
            if (o != address(0)) rows[id - from] = Cell(o, listing[id], uint16(boostOf(id)), uint8(terrainOf(id)));
        }
    }
    function stats() external view returns (uint256[14] memory s) {
        s = [totalMinted, totalMined, vaultTotalIn, vaultTotalClaimed, marketVolume, marketSales, machinesMinted[0],
            revealed ? 1 : 0, mintOpen ? 1 : 0, openToAll ? 1 : 0, miningOpen ? 1 : 0, machinesOpen ? 1 : 0, marketOpen ? 1 : 0, miningStart];
    }

    function tokenURI(uint256 id) public view override returns (string memory) {
        _requireOwned(id);
        uint256 t = terrainOf(id);
        uint256 seed = uint256(keccak256(abi.encode(id, "mars")));
        string memory img = Base64.encode(bytes(ART.plotSvg(id, seed, t, revealed, _mach[id], plotName[id])));
        string memory attrs = string.concat("[{\"trait_type\":\"X\",\"display_type\":\"number\",\"value\":", ((id - 1) % 100).toString(),
            "},{\"trait_type\":\"Y\",\"display_type\":\"number\",\"value\":", ((id - 1) / 100).toString(),
            "},{\"trait_type\":\"Terrain\",\"value\":\"", revealed ? ART.terrainName(t) : "Unsurveyed",
            "\"},{\"trait_type\":\"Machine Slots\",\"display_type\":\"number\",\"value\":", slotsOf(id).toString(),
            "},{\"trait_type\":\"Boost %\",\"display_type\":\"number\",\"value\":", boostOf(id).toString(), "}]");
        return string.concat("data:application/json;base64,", Base64.encode(bytes(string.concat(
            "{\"name\":\"Mars Plot #", id.toString(),
            "\",\"description\":\"MARS PLOTS: 10,000 land plots on Mars, BNB Chain. Mine REGO daily, boost with machines. 100% on-chain. https://marsplots.pages.dev\",\"image\":\"data:image/svg+xml;base64,",
            img, "\",\"attributes\":", attrs, "}"))));
    }
    function contractURI() external pure returns (string memory) {
        return "data:application/json;utf8,{\"name\":\"MARS PLOTS\",\"description\":\"10,000 land plots on Mars. One per wallet, free for .ai Agent ID holders. Mine REGO daily and boost with machines.\",\"external_link\":\"https://marsplots.pages.dev\"}";
    }

    // ---------------- internals ----------------
    function _update(address to, uint256 id, address auth) internal override returns (address from) {
        from = super._update(to, id, auth);
        if (listing[id] != 0) { delete listing[id]; emit Unlisted(id); }
    }
    function _pay(address payable to, uint256 amt) private {
        if (amt == 0) return;
        (bool ok,) = to.call{value: amt}("");
        require(ok, "pay failed");
    }
    function supportsInterface(bytes4 i) public view override(ERC721, ERC2981) returns (bool) {
        return i == bytes4(0x49064906) || super.supportsInterface(i);
    }
}
